def mirror_check_work(
    bridges, links, delay, bridge_name, ports, age, storm, lags, max_frame,
    events, limit
):
    """mirror-check 的工作量预演：独立链路副本与空状态，无副作用。

    计费与 mirror 完全一致；坏帧不改变 FDB 与风暴/迁移队列，仍按帧计入
    每帧开销。累计等于上限合法，首次超过即抛 MirrorWorkLimit。
    """
    window = storm["window"]
    limits = storm["limits"]
    move_limit = storm["move_limit"]
    hold = storm["hold"]
    B = len(bridges)
    L = len(links)
    P = len(ports)
